scripts.run_ct46.ps1:
param([Parameter(ValueFromRemainingArguments=$true)][string[]]$TrialArguments)
$ErrorActionPreference='Stop'
$trialContainer=(docker inspect caliburn-q019-postgres | ConvertFrom-Json)[0]
if ($LASTEXITCODE -ne 0 -or $trialContainer.State.Status -ne 'running') { throw 'Test DB unavailable' }
$trialSettings=@{}
foreach ($entry in $trialContainer.Config.Env) { $pair=$entry.Split('=',2); $trialSettings[$pair[0]]=$pair[1] }
if ($trialSettings.POSTGRES_DB -ne 'q019_agent_test' -or $trialSettings.POSTGRES_USER -ne 'q019' -or $trialContainer.NetworkSettings.Ports.'5432/tcp'[0].HostPort -ne '55433') { throw 'Unexpected DB target' }
$env:Q019_TEST_DATABASE_URL='postgresql://q019:'+ [uri]::EscapeDataString($trialSettings.POSTGRES_PASSWORD) +'@127.0.0.1:55433/q019_agent_test?connect_timeout=5'
$env:PYTHONUTF8='1'; $env:PYTHONPATH='src'
try { & .venv/Scripts/python.exe .test-tmp/ct46_replay.py @TrialArguments; $trialExit=$LASTEXITCODE }
finally { Remove-Item Env:Q019_TEST_DATABASE_URL -ErrorAction SilentlyContinue; $trialSettings.Clear() }
exit $trialExit

